def get_extra_works_df() -> pd.DataFrame:
    return pd.DataFrame(EXTRA_WORKS_MASTER)

def calculate_ew_item_cost(item: Dict[str, Any]) -> float:
    unit_price = float(item.get('Unit_Price', 0.0))
    quantity = float(item.get('Quantity', 0.0))
    return round(unit_price * quantity, 2)

def calculate_total_ew_cost(selected_items: List[Dict[str, Any]]) -> float:
    return round(sum(calculate_ew_item_cost(item) for item in selected_items), 2)
